define(['jquery', 'core/log', 'mod_minilesson/progresstimer'], function ($, log) {
    return {
        index: 0,
        quizhelper: null,
        itemdata: {},
        container: null,
        swiperpromise: null,

        clone: function () {
            return $.extend(true, { correctitems: 0, totalitems: 0 }, this);
        },

        next_question: function () {
            const stepdata = {};
            stepdata.index = this.index;
            stepdata.hasgrade = false;
            stepdata.totalitems = this.totalitems;
            stepdata.correctitems = this.correctitems;
            stepdata.grade = this.totalitems > 0 ? 100 * this.correctitems / this.totalitems : 0;
            this.quizhelper.do_next(stepdata);
        },

        init: function (index, itemdata, quizhelper) {
            this.index = index;
            this.itemdata = itemdata;
            this.quizhelper = quizhelper;
            this.container = document.querySelector(`#${itemdata.uniqueid}_container`);
            this.$container = $(this.container);
            this.nextbutton = this.container.querySelector('.minilesson_nextbutton');
            this.register_events();
            // Start fetching Swiper now rather than when the item is shown, so the carousel is
            // interactive as soon as it appears.
            this.load_swiper();
            return this;
        },

        register_events() {
            // The next button is absent for a single ungradeable item (no quizfinished page).
            if (this.nextbutton) {
                this.nextbutton.addEventListener('click', e => {
                    e.preventDefault();
                    this.next_question();
                });
            }
            this.$container.on('showElement', () => {
                this.load_swiper().then(Swiper => this.init_swiper(Swiper)).catch(log.debug);
            });
            this.init_card_audio();
        },

        /**
         * Wire up the per-card audio players: mutual exclusion between the line 1 and line 3
         * players, icon state syncing, and tap-to-play on card line 3.
         */
        init_card_audio() {
            this.container.querySelectorAll('.swiper-slide').forEach((slide) => {
                const audios = Array.from(slide.querySelectorAll('audio'));

                // Only one player per card should sound at a time: starting one pauses the others.
                audios.forEach((audio) => {
                    audio.addEventListener('play', () => {
                        audios.forEach((other) => {
                            if (other !== audio) {
                                other.pause();
                            }
                        });
                    });
                });

                // Keep the line 1 round button icon in sync when its player is paused externally
                // (mod_minilesson/ttsaudio only updates the icon on its own click and on 'ended').
                const line1audio = slide.querySelector('audio.mod_minilesson_itemttsaudio');
                if (line1audio) {
                    line1audio.addEventListener('pause', () => {
                        const icon = slide.querySelector('.samplettsaudio .fa');
                        if (icon) {
                            icon.classList.remove('fa-stop');
                            icon.classList.add('fa-volume-up');
                        }
                    });
                }

                // Line 3: tapping the line or its speaker icon toggles playback of the hidden player.
                const line3 = slide.querySelector('.cardline3-playable');
                if (line3) {
                    const audio = line3.querySelector('audio.cardline3-audio');
                    const icon = line3.querySelector('.cardline3-audio-btn .fa');
                    const showplaying = (playing) => {
                        icon.classList.toggle('fa-stop', playing);
                        icon.classList.toggle('fa-volume-up', !playing);
                    };
                    audio.addEventListener('play', () => showplaying(true));
                    audio.addEventListener('pause', () => showplaying(false));
                    audio.addEventListener('ended', () => showplaying(false));
                    line3.addEventListener('click', (e) => {
                        e.preventDefault();
                        if (!audio.paused && !audio.ended) {
                            audio.pause();
                            audio.currentTime = 0;
                        } else {
                            audio.play();
                        }
                    });
                }
            });
        },

        /**
         * Lazy-load the Swiper library.
         *
         * Swiper is a >100kb MIT library vendored with the plugin (amd/src/external/swiper-lazy.js)
         * rather than pulled from a CDN, so it keeps working on networks that cannot reach
         * jsdelivr/cdnjs (e.g. China). Loading it on demand keeps it off the critical path of
         * lessons that contain no cards item.
         *
         * Its stylesheet is not loaded here: itemtype::page_requirements() puts it in the page
         * head, because the un-styled carousel markup lays every card out side by side.
         *
         * The load is started at init() and only awaited when the item is shown, so by the time
         * the learner reaches the card it is normally already resolved.
         *
         * @returns {Promise} resolves with the Swiper constructor.
         */
        load_swiper() {
            if (!this.swiperpromise) {
                this.swiperpromise = new Promise((resolve, reject) => {
                    require(['mod_minilesson/external/swiper-lazy'], function(Swiper) {
                        resolve(Swiper.default || Swiper);
                    }, reject);
                });
            }
            return this.swiperpromise;
        },

        init_swiper(Swiper) {
            const swiperel = this.container.querySelector('.swiper');
            const swiper = new Swiper(swiperel, {
                direction: 'horizontal',
                loop: false,
                autoHeight: true,
                pagination: {
                    el: '.swiper-pagination',
                    type: 'fraction',
                },
                navigation: {
                    addIcons: false,
                    nextEl: '.swiper-button-next',
                    prevEl: '.swiper-button-prev',
                },
                on: {
                    slideChange: () => {
                        const previousIndex = swiper.previousIndex;
                        const currentIndex = swiper.activeIndex;

                        const previousSlideEl = swiper.slides[previousIndex];
                        const currentSlideEl = swiper.slides[currentIndex];

                        this.settleAudioPlayback(previousSlideEl, false);
                        this.settleAudioPlayback(currentSlideEl, true);
                    },
                }
            });
            this.settleAudioPlayback(swiper.slides[swiper.activeIndex], true);
            if (this.itemdata.timelimit > 0) {
                this.$container.find(".progress-container").show();
                this.$container.find(".progress-container i").show();
                this.$container.find(".progress-container #progresstimer").progressTimer({
                    height: '5px',
                    timeLimit: this.itemdata.timelimit,
                    onFinish: () => {
                        if (this.nextbutton) {
                            this.nextbutton.click();
                        }
                    }
                });
            }
        },

        settleAudioPlayback(slideEl, play) {
            if (!play) {
                slideEl.querySelectorAll('audio').forEach((audio) => audio.pause());
                return;
            }
            // Only the line 1 player ever autoplays; line 3 audio is strictly tap-to-play.
            const line1audio = slideEl.querySelector('audio.mod_minilesson_itemttsaudio');
            if (line1audio && line1audio.dataset.autoplay === '1') {
                line1audio.play();
            }
        }
    };
});